import { test, expect } from '@playwright/test';

const BASE_URL = process.env.TARGET_URL || 'https://adactinhotelapp.com/';
const USERNAME = process.env.TARGET_USERNAME || 'ADACTINFORQA';
const PASSWORD = process.env.TARGET_PASSWORD || '3U0515';

test('Successful login with valid credentials', async ({ page }) => {
  // Step 1: Navigate to the application base URL
  console.log('[Timeline] Navigate: to application base URL');
  await page.goto(BASE_URL);

  // Step 2: Enter username into the Username field
  console.log('[Timeline] Type: enter username into Username field');
  await page.locator('input#username').fill(USERNAME);

  // Step 3: Enter password into the Password field
  console.log('[Timeline] Type: enter password into Password field');
  await page.locator('input#password').fill(PASSWORD);

  // Step 4: Click the Login button
  console.log('[Timeline] Click: Login button');
  await page.locator('input#login').click();

  // Expected result: User is redirected to Search Hotel page and welcome message is displayed
  await expect(page).toHaveURL(/SearchHotel\.php/);
  await expect(page.locator('input#username_show')).toHaveValue('Hello ADACTINFORQA!');
});
